def get_reksa_balance():
    # get reksadana balance
    reksa_used_cols = getConfig("customer_data_preprocessing", "reksa_used_cols")
    db = "dm_analytics"
    table = "dm_reksadana"
    queries = "SELECT {} FROM {}.{}".format(",".join(reksa_used_cols), db, table)
    df_reksa = spark.sql(
        queries
    )  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_reksadana (K7 tables, K4-TBL-004)
    df_reksa = df_reksa.withColumnRenamed("cif", "cif_number")
    df_reksa = df_reksa.repartition("cif_number")

    coln = "report_date"
    df_reksa = df_reksa.withColumn(coln, F.to_date(coln, format="yyyyMMdd"))
    df_reksa = df_reksa.withColumn(coln, df_reksa[coln].cast("string"))

    coln = "holding_date"
    df_reksa = df_reksa.withColumn(coln, F.to_date(coln, format="yyyyMMdd"))
    df_reksa = df_reksa.withColumn(coln, df_reksa[coln].cast("string"))
    df_reksa = df_reksa.withColumn(
        "account_open_date", F.min(coln).over(Window.partitionBy("cif_number", "ifua"))
    )
    df_reksa = df_reksa.drop(coln)

    # Filter akun yang dibuka
    df_reksa = df_reksa.filter(F.col("account_open_date") <= max_date)

    # Filter akun report date
    df_reksa = df_reksa.filter(F.col("report_date") == max_date)
    df_reksa = df_reksa.groupby("cif_number").agg(
        F.sum("nilai_tunai_idr").alias("reksa_balance")
    )
    return df_reksa


def get_banca_balance():
    banca_used_cols = getConfig("customer_data_preprocessing", "banca_used_cols")
    db = "dm_analytics"
    table = "dm_banca_aum_summary"
    queries = "SELECT {} FROM {}.{}".format(", ".join(banca_used_cols), db, table)
    df_banca = spark.sql(
        queries
    )  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_banca_aum_summary (K7 tables, K4-TBL-004)
    df_banca = df_banca.withColumnRenamed(
        "cif_number_by_disburse_account", "cif_number"
    )

    coln = "report_date"
    df_banca = df_banca.withColumn(coln, F.to_date(coln, format="yyyyMMdd"))
    df_banca = df_banca.withColumn(coln, df_banca[coln].cast("string"))

    coln = "pinbook_date"
    df_banca = df_banca.withColumn(coln, F.to_date(coln, format="yyyyMMdd"))
    df_banca = df_banca.withColumn(coln, df_banca[coln].cast("string"))
    df_banca = df_banca.withColumnRenamed("pinbook_date", "account_open_date")

    # Filter akun yang dibuka
    df_banca = df_banca.filter(F.col("account_open_date") <= max_date)
    df_banca = df_banca.filter(F.col("account_open_date") != "2000-01-01")

    # Filter report_date
    df_banca = df_banca.filter(F.col("report_date") == max_date)
    df_banca = df_banca.groupby("cif_number").agg(
        F.sum("aum_idr").alias("banca_balance")
    )
    return df_banca


