    if len(notUpdatedTable) == 1:
        s = notUpdatedTable[-1]
        raise AttributeError(f"{s} table is not updated")
    else:
        s = ", ".join(notUpdatedTable[:-1])
        s = f"{s}, and {notUpdatedTable[-1]}"
        raise AttributeError(f"{s} tables are not updated")

